//! Python code-style pages; edits feed the shared formatter, not a preview model.
use super::*;
use crate::a11y::AccessibleCombo;
use rustpy_settings::python_style::{SPACE_OPTIONS, WRAP_OPTIONS};
impl IdeApp {
    pub(super) fn python_style_page(&mut self, ui: &mut egui::Ui) {
        ui.collapsing("Python code style pages",|ui|{
   if self.settings_ui.python_style_page.is_empty(){self.settings_ui.python_style_page="Tabs and Indents".into()}
   ui.horizontal_wrapped(|ui|{for page in ["Tabs and Indents","Spaces","Wrapping and Braces","Blank Lines","Imports","Other","Arrangement","Code Generation"]{ui.selectable_value(&mut self.settings_ui.python_style_page,page.into(),crate::i18n::tr_static(page));}});
   let page=self.settings_ui.python_style_page.clone();let python=&mut self.settings.code_style.python;
   match page.as_str(){
    "Tabs and Indents"=>{let indent=&mut python.indents;ui.checkbox(&mut indent.smart_tabs,"Smart tabs (tabs for blocks, spaces for alignment)");ui.add(egui::Slider::new(&mut indent.continuation,1..=32).text("Continuation indent"));ui.checkbox(&mut indent.keep_empty,"Keep indents on empty lines");ui.checkbox(&mut indent.in_parentheses,"Indent in parentheses");ui.checkbox(&mut indent.hanging_closing,"Hang closing brackets");ui.checkbox(&mut indent.parameters,"Use continuation indent for declaration parameters");ui.checkbox(&mut indent.arguments,"Use continuation indent for call arguments");ui.checkbox(&mut indent.collections,"Use continuation indent for collections/comprehensions");},
    "Spaces"=>{for(key,label)in SPACE_OPTIONS{let default=!matches!(*key,"operator_at_line_end"|"before_call"|"before_declaration"|"before_subscript"|"keyword_equals"|"default_equals"|"power"|"within_parentheses"|"within_brackets"|"within_braces"|"empty_call"|"before_dict_colon"|"before_slice_colon"|"after_slice_colon"|"before_annotation_colon"|"before_lambda_colon"|"after_unpack");let mut value=python.space(key,default);if ui.checkbox(&mut value,*label).changed(){python.spaces.insert((*key).into(),value);}}if ui.button("Restore default spaces").clicked(){python.spaces.clear();}},
    "Wrapping and Braces"=>{for(key,label)in WRAP_OPTIONS{ui.collapsing(*label,|ui|{let original=python.wrap(key);let mut rule=original.clone();egui::ComboBox::from_id_salt(("wrap_python",key)).selected_text(&rule.mode).show_ui(ui,|ui|{for(mode,label)in [("inherit","Formatter default"),("never","Do not wrap"),("if_long","Wrap if long"),("chop","Chop down if long"),("always","Wrap always")]{ui.selectable_value(&mut rule.mode,mode.into(),crate::i18n::tr_static(label));}}).combo_named(label);ui.checkbox(&mut rule.align,"Align when multiline");ui.checkbox(&mut rule.newline_after_open,"New line after opening bracket");ui.checkbox(&mut rule.closing_on_newline,"Closing bracket on new line");if rule!=original{python.wrapping.insert((*key).into(),rule);}});}let mut after=python.space("operator_at_line_end",false);if ui.checkbox(&mut after,"Binary operator at end of wrapped line").changed(){python.spaces.insert("operator_at_line_end".into(),after);}ui.checkbox(&mut python.force_after_colon,"Force line break after block colon (including stubs)");},
    "Blank Lines"=>{let b=&mut python.blank_lines;for(value,label)in [(&mut b.max_declarations,"Keep maximum in declarations"),(&mut b.max_code,"Keep maximum in code"),(&mut b.before_imports,"Before imports"),(&mut b.after_imports,"After module imports"),(&mut b.before_first_method,"Before first method"),(&mut b.after_local_imports,"After local imports"),(&mut b.before_class_docstring,"Before class docstring"),(&mut b.after_class_docstring,"After class docstring")]{ui.add(egui::Slider::new(value,0..=10).text(label));}ui.label("Around top-level definitions and methods: controls below.");},
    "Imports"=>{let imports=&mut python.imports;if ui.checkbox(&mut imports.force_from,"Prefer from style for generated imports and equivalent aliases").changed(){self.settings.refactoring.prefer_from_imports=imports.force_from;}for(value,label)in [(&mut imports.sort,"Sort imports"),(&mut imports.case_insensitive,"Case-insensitive sort"),(&mut imports.modules_first,"Sort modules before symbols"),(&mut imports.join_from,"Join from-imports from same source"),(&mut imports.align,"Align parenthesized from imports"),(&mut imports.group,"Group standard library / third party / project"),(&mut imports.remove_unused_only,"Optimize: remove unused only"),(&mut imports.preserve_order,"Preserve order"),(&mut imports.import_before_from,"Place import before from"),(&mut imports.parentheses,"Add parentheses to from imports"),(&mut imports.trailing_comma,"Trailing comma in multiline from imports")]{ui.checkbox(value,crate::i18n::tr_static(label));}egui::ComboBox::from_id_salt("relative_import_style").selected_text(&imports.relative_style).show_ui(ui,|ui|{for value in ["preserve","relative","absolute"]{ui.selectable_value(&mut imports.relative_style,value.into(),crate::i18n::tr_static(value));}}).combo_named(crate::i18n::tr_static("Relative import style"));},
    "Other"=>{for(field,label)in [(&mut python.dict_alignment,"Dictionary alignment"),(&mut python.docstring_quotes,"Docstring quotes"),(&mut python.type_hint_quotes,"Type-hint quotes")]{let choices: &[&str]=if label=="Dictionary alignment"{&["none","keys","values"]}else{&["inherit","preserve","single","double"]};egui::ComboBox::from_id_salt(label).selected_text(field.as_str()).show_ui(ui,|ui|{for value in choices{ui.selectable_value(field,(*value).into(),*value);}}).combo_named(crate::i18n::tr_static(label));}ui.checkbox(&mut python.multiline_trailing_comma,"Add trailing comma on multiline collections/calls");ui.checkbox(&mut python.explicit_continuation,"Use backslash continuation instead of redundant grouping");ui.checkbox(&mut python.first_column_comments,"Keep comments at first column");ui.checkbox(&mut python.space_after_comment,"Add space after #");ui.add(egui::Slider::new(&mut python.spaces_before_comment,0..=8).text("Spaces before inline comment"));},
    "Arrangement"=>{ui.checkbox(&mut python.arrangement.enabled,"Enable guarded Rearrange Code");ui.label("Rule order (comma separated): dunder, class_variables, static, abstract, public, protected, private");let mut order=python.arrangement.order.join(", ");if ui.text_edit_singleline(&mut order).changed(){python.arrangement.order=order.split(',').map(str::trim).filter(|name|matches!(*name,"dunder"|"class_variables"|"static"|"abstract"|"public"|"protected"|"private")).map(String::from).collect();}ui.label("Computed defaults, unknown decorators, comments and duplicate names retain execution order.");},
    "Code Generation"=>{ui.checkbox(&mut python.first_column_comments,"Line comments at first column");ui.checkbox(&mut python.space_after_comment,"Add space after line-comment marker");ui.checkbox(&mut python.self_type_hints,"Generate quoted self / cls type hints");let old_docstring_style=python.docstring_style.clone();egui::ComboBox::from_id_salt("python_docstring_style").selected_text(&python.docstring_style).show_ui(ui,|ui|{for value in ["auto","plain","rest","epytext","google","numpy"]{ui.selectable_value(&mut python.docstring_style,value.into(),crate::i18n::tr_static(value));}}).combo_named(crate::i18n::tr_static("Docstring format"));if python.docstring_style!=old_docstring_style{self.settings.docstring_format=python.docstring_style.clone();}},_=>{}}
  });
    }
}
